export function resourceFit(b,{assets,skill,capital}){const reused=b.assets.filter(x=>assets.includes(x)),missing=b.assets.filter(x=>!assets.includes(x));return {reused,missing,skillMatch:b.skill===skill||(b.skill==='livestock'&&skill==='farming'),gap:Math.max(0,b.cost-capital),score:reused.length*3-missing.length*4+(b.skill===skill||(b.skill==='livestock'&&skill==='farming')?3:0)+(capital>=b.cost?2:0)};}
export function assess({business,resources,economics,knownCompetitors=null,demand=null,mappedCount=null}){
 const fit=resourceFit(business,resources),margin=economics.price-economics.variable;
 const be=margin>0?Math.ceil(economics.fixed/margin):null;
 const competition=Math.max(knownCompetitors??0,mappedCount??0);
 const reasons=[],tasks=[];let caution=false;
 if(!fit.skillMatch){caution=true;reasons.push('Your selected skill does not match this business; training or an experienced partner is needed.');}
 if(fit.missing.length){caution=true;reasons.push('Some required resources are missing.');}
 if(fit.gap>0){caution=true;reasons.push('Illustrative startup cost exceeds available investment.');}
 if(margin<=0){caution=true;reasons.push('Selling price does not cover variable cost; increasing sales cannot cover fixed costs.');}
 if(demand!==null&&be!==null&&demand<be){caution=true;reasons.push(`Your estimated obtainable sales (${demand} units/month) are below operating break-even (${be} units/month).`);}
 if(competition>=5){caution=true;reasons.push(`${competition} reported or mapped similar-business signals suggest competition to investigate. This is a heuristic, not proof of saturation.`);}
 const unknownDemand=demand===null,unknownCompetition=knownCompetitors===null&&(mappedCount===null||mappedCount===0);
 if(unknownDemand)tasks.push('Interview buyers and estimate the monthly sales you can realistically win.');
 if(unknownCompetition)tasks.push('Check nearby competing businesses and compare pricing and capacity.');
 if(mappedCount===0)tasks.push('No relevant mapped entries were found. Local competition may still exist.');
 tasks.push(business.check);
 const status=caution?'Rework before investing':unknownDemand||unknownCompetition?'More evidence needed':'Worth a small pilot';
 if(!reasons.length)reasons.push(status==='Worth a small pilot'?'The entered resources and assumptions do not trigger a caution flag; validate them with a small pilot.':'There is not enough evidence to assess local market viability yet.');
 return {status,reasons,tasks,fit,breakEven:be,competition,demand,unknownDemand,unknownCompetition};
}
export function alternatives(intended,resources){return businesses.filter(x=>x.id!==intended.id).map(x=>{const fit=resourceFit(x,resources);const shared=x.assets.filter(a=>intended.assets.includes(a)&&resources.assets.includes(a)).length;return {...x,fit:{...fit,score:fit.score+shared*4}};}).filter(x=>x.fit.reused.length>0).sort((a,b)=>b.fit.score-a.fit.score||a.cost-b.cost).slice(0,3);}
export function matches(b,tags){return b.tags.some(([key,value])=>tags?.[key]===value);}
